<head>
    <title></title>
    <style type="text/css">
        body {
            font-family: "Helvetica Neue", "Lucida Grande", "Segoe UI", Arial, Helvetica, Verdana, sans-serif;
            font-size: 10pt;
        }

        .header {
            background-color: #ffc000;
            color: #ffffff;
            font-weight: bold;
            font-size: 16px;
            padding: 10px 10px 10px 10px;
        }
		
		.footer {
			background-color: #ffc000;
			height: 10px;
		}

        .main {
            padding: 10px 10px 10px 10px;
            border-top: 1px solid grey;
        }
    </style>
</head>
<body>
    <div class="header">Ekurhuleni Siyakhokha</div>
    <div class="main">
			<br/>
            Dear <b>#NAME#</b>,<br />
            <br />
            #BODYTEXT#
            <br />
			<br/>
            Regards,<br />
            <b>Siyakhokha Team</b>
            <br />
            <br />
    </div>
</body>
<div class="footer">&nbsp;</div>
</html>', 1, 0, NULL, NULL, GETDATE(), NULL, GETDATE(), NULL);
